(function(){var bar=document.getElementById("pr-mobile-book");var form=document.getElementById("contact_form");if(!bar||!form||!("IntersectionObserver"in window))return;var mq=window.matchMedia("(max-width: 991px)");var formVisible=false;function update(){var on=mq.matches&&!formVisible;bar.classList.toggle("is-on",on);document.body.classList.toggle("pr-mb-on",on);bar.setAttribute("aria-hidden",on?"false":"true")}new IntersectionObserver(function(entries){formVisible=entries[0].isIntersecting;update()},{rootMargin:"0px 0px -45% 0px"}).observe(form);if(mq.addEventListener)mq.addEventListener("change",update);var source=document.getElementById("car-price-sidebar");var target=document.getElementById("pr-mb-price");if(source&&target){var copy=function(){var text=(source.textContent||"").trim();if(/\d/.test(text))target.textContent=text};new MutationObserver(copy).observe(source,{childList:true,characterData:true,subtree:true});copy()}bar.querySelector("a").addEventListener("click",function(e){e.preventDefault();form.scrollIntoView({behavior:"smooth",block:"start"})});update()})();